# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "tool forms": result views that show the inputs of the agent tool that made them, to
#          change and run again; the Results tab bar's "+" adds one by hand. Generic: a form is
#          built from a tool's parameter schema, the very one pydantic-ai gives the model (names,
#          types, defaults, choices, descriptions), and its values are checked by the tool's own
#          argument validator, so a form can't drift from its tool. Which inputs made a result is
#          recorded by the session (Session.calls), not read off the result.
#          Which widgets have one is in widgets.py (Widget.tool); this file is the generic part.
# ---------------------------------------------------------------------------
from __future__ import annotations

import dataclasses
import typing
from functools import cached_property
from typing import TYPE_CHECKING, Any

from pydantic import ValidationError
from pydantic_ai import Tool

if TYPE_CHECKING:
    from collections.abc import Callable


@dataclasses.dataclass
class FormField:
    """One tool parameter as the browser shows it."""

    name: str
    label: str
    kind: str = "text"
    """text | number | select | check"""
    value: str = ""
    options: list[str] = dataclasses.field(default_factory=list)
    """select only; "" means not set."""
    help: str = ""
    """The parameter's description from the tool's schema, shown as the field's tooltip."""


def schema_fields(schema: dict[str, Any], values: dict[str, Any], hide: tuple[str, ...] = ()) -> list[FormField]:
    """Form fields for a JSON schema's properties (an object schema, as pydantic makes for a
    function's parameters or a model), filled from values, else each property's default.

    string -> text, integer / number -> number, boolean -> check, a fixed set of values (enum /
    const, also inside anyOf) -> select. Anything else is a text box.
    """
    fields = []
    for name, prop in schema.get("properties", {}).items():
        if name in hide:
            continue
        options = _choices(prop)
        kind = (
            "select"
            if options
            else {"integer": "number", "number": "number", "boolean": "check"}.get(prop.get("type", ""), "text")
        )
        value = values.get(name, prop.get("default", ""))
        fields.append(
            FormField(
                name=name,
                label=name.replace("_", " "),
                kind=kind,
                value="on" if value is True else "" if value in (None, False) else str(value),
                # "not set" first
                options=sorted(options, key=bool),
                help=" ".join(str(prop.get("description", "")).split()),
            )
        )
    return fields


def _choices(prop: dict[str, Any]) -> list[str]:
    """A property's fixed set of values ([] if it is free): enum / const, directly or in every anyOf branch."""
    branches = prop.get("anyOf") or [prop]
    options: list[str] = []
    for branch in branches:
        if "enum" in branch:
            options += [str(option) for option in branch["enum"]]
        elif "const" in branch:
            options.append(str(branch["const"]))
        else:
            return []
    return options


@dataclasses.dataclass
class ToolRequest:
    """A tool form not run yet (added with "+"): a placeholder value shown as just the form.
    Running it replaces it with the tool's result."""

    form: str
    """The ToolForm's key."""
    inputs: dict[str, Any] = dataclasses.field(default_factory=dict)


@dataclasses.dataclass
class ToolForm:
    title: str
    """What the "+" menu calls it, eg 'Match videos'."""
    function: Callable[..., Any]
    """The agent's tool function. Its return annotation is the result type that gets the form."""
    hide: tuple[str, ...] = ()
    """Parameters not on the form (they keep their defaults), eg paging the view does itself."""

    @cached_property
    def tool(self) -> Tool:
        return Tool(self.function)

    @property
    def key(self) -> str:
        return self.tool.name

    @cached_property
    def schema(self) -> dict[str, Any]:
        """The parameters' JSON schema, as the model gets it."""
        return self.tool.tool_def.parameters_json_schema

    @cached_property
    def result_type(self) -> type:
        return typing.get_type_hints(self.function)["return"]

    def fields(self, values: dict[str, Any]) -> list[FormField]:
        return schema_fields(self.schema, values, self.hide)

    def arguments(self, raw: dict[str, Any]) -> dict[str, Any]:
        """A submitted form as the tool's arguments, checked by the validator pydantic-ai uses for
        the model's calls. Raises ValueError naming the bad fields."""
        given: dict[str, Any] = {}
        for name, prop in self.schema.get("properties", {}).items():
            if name in self.hide:
                continue
            value = raw.get(name, "")
            if prop.get("type") == "boolean":
                # an unticked checkbox is missing from (or falsy in) the submitted form
                given[name] = value not in ("", None, False, "false", "off")
            elif isinstance(value, str) and prop.get("type") != "string" and not _choices(prop):
                if value.strip():  # an empty number box = the default
                    given[name] = value.strip()
            else:
                given[name] = value.strip() if isinstance(value, str) else value
        try:
            return self.tool.function_schema.validator.validate_python(given)
        except ValidationError as error:
            problems = [f"{'.'.join(map(str, e['loc']))}: {e['msg']}" for e in error.errors()]
            raise ValueError("; ".join(problems)) from error

    def run(self, raw: dict[str, Any]) -> tuple[Any, dict[str, Any]]:
        """Run the tool with a submitted form: (its result, the inputs used, for Session.calls)."""
        arguments = self.arguments(raw)
        shown = {name: value for name, value in arguments.items() if name not in self.hide}
        return self.function(**arguments), shown
